import { test, expect } from '@playwright/test';

test.describe('Регистрация и вход — валидация', () => {
  test('Пустые поля входа и регистрации — сообщения обязательных полей #ec8ab82d #7be18ee9 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /sign-in, click the submit button "כניסה" with empty fields
    await page.goto('/sign-in');
    await page.getByRole('button', { name: 'כניסה', exact: true }).last().click();
    await expect(page.getByText('יש להזין אימייל').locator('visible=true')).toBeVisible();
    await expect(page.getByText('יש להזין סיסמה').locator('visible=true')).toBeVisible();
    await expect(page).toHaveURL(/\/sign-in$/);

    // 2. Open /sign-up, click "יצירת חשבון" with empty fields
    await page.goto('/sign-up');
    await page.getByRole('button', { name: 'יצירת חשבון', exact: true }).last().click();
    await expect(page.getByText('יש להזין אימייל').locator('visible=true')).toBeVisible();
    await expect(page.getByText('יש להזין סיסמה').locator('visible=true')).toBeVisible();
    await expect(page).toHaveURL(/\/sign-up$/);
  });
});
